begin;
select plan(52);
select has_table('public', 'event_covers', 'Cover references are isolated');
select has_table('public', 'event_cover_operations', 'Operations are durable');
select has_table('public', 'event_cover_cleanup_jobs', 'Cleanup is durable');
select is((select count(*) from public.events e left join public.event_covers c on c.event_id=e.id where c.event_id is null), 0::bigint, 'All historical Events backfilled');
select ok(not exists(select 1 from public.event_covers where revision<>0 or object_path is not null), 'Upgrade starts at empty revision 0');
select ok((select bool_and(relrowsecurity) from pg_class where oid in ('public.event_covers'::regclass,'public.event_cover_operations'::regclass,'public.event_cover_cleanup_jobs'::regclass)), 'All technical tables have RLS');
select ok(not has_table_privilege('anon','public.event_covers','select'), 'Anon cannot read cover rows');
select ok(has_table_privilege('authenticated','public.event_covers','select'), 'Owner read enabled through RLS');
select ok(not has_table_privilege('authenticated','public.event_covers','update'), 'No cover bypass');
select ok(not has_table_privilege('authenticated','public.event_cover_operations','select'), 'No general ledger access');
select ok(not has_table_privilege('authenticated','public.event_cover_cleanup_jobs','select'), 'No cleanup access');
select ok(not has_function_privilege('authenticated','public.lock_event_cover(uuid,uuid)','execute'), 'Internal owner lock is service-only');
select is((select public from storage.buckets where id='event-cover-uploads'), false, 'Staging is private');
select is((select public from storage.buckets where id='event-covers'), true, 'Final cover allows opaque public download');
select is((select file_size_limit from storage.buckets where id='event-cover-uploads'), 5242880::bigint, 'Inclusive bucket byte limit');
select is((select file_size_limit from storage.buckets where id='event-covers'), 5242880::bigint, 'Final cover bucket byte limit reconciled');
select is((select allowed_mime_types from storage.buckets where id='event-cover-uploads'), array['application/octet-stream'], 'Existing staging bucket MIME restriction reconciled');
select is((select allowed_mime_types from storage.buckets where id='event-covers'), array['image/jpeg','image/png','image/webp'], 'Existing final bucket MIME restrictions reconciled');
select throws_ok($$update public.event_covers set position_x='NaN'::float8$$, '23514', null, 'NaN position forbidden');
select throws_ok($$update public.event_covers set position_y='Infinity'::float8$$, '23514', null, 'Infinite position forbidden');
select throws_ok($$update public.event_covers set object_path='covers/arbitrary'$$, '23514', null, 'Arbitrary paths forbidden');
select throws_ok($$update public.event_covers set alt_text='Text on absent file'$$, '23514', null, 'Absent file has no custom alt');
select throws_ok($$update public.event_covers set revision=-1$$, '23514', null, 'Negative revision forbidden');
select throws_ok($$update public.event_covers set width=640$$, '23514', null, 'Partial file metadata forbidden');
select ok(not exists(select 1 from pg_policies where schemaname='storage' and tablename='objects' and (qual like '%event-cover%' or with_check like '%event-cover%')), 'No browser storage policy added');
select lives_ok($$select public.lock_event_cover('72000000-0000-4000-8000-000000000001','71000000-0000-4000-8000-000000000001')$$, 'Owner accepted');
select throws_ok($$select public.lock_event_cover('72000000-0000-4000-8000-000000000001','71000000-0000-4000-8000-000000000002')$$, '42501', 'cover_forbidden', 'Other actor forbidden');
select has_function('public','get_event_cover_state',array['uuid','uuid'], 'Authorized current state RPC exists');
select has_function('public','prepare_event_cover_upload',array['uuid','uuid','text','bigint','text','jsonb'], 'Durable signed-upload preparation exists');
select has_function('public','claim_event_cover_upload',array['uuid','uuid','text','bigint','text','jsonb','text','text','jsonb'], 'Fenced upload claim exists');
select has_function('public','finish_event_cover_upload',array['uuid','uuid','text','text','jsonb'], 'Authorized CAS commit exists');
select ok((select bool_and(to_jsonb(e) ? 'cover') from public.get_public_event_list() e), 'Public listing includes nullable cover');
select ok((select public.get_public_event_registration(public_code)->'event' ? 'cover' from public.events where id='72000000-0000-4000-8000-000000000001'), 'Public registration includes nullable cover');
select has_function('public','mutate_event_cover',array['uuid','uuid','text','text','bigint','text','jsonb'], 'Metadata and removal use authorized durable CAS');
insert into public.events(id,created_by,title,venue,event_date,max_capacity,time_zone,registration_closes_at,entry_opens_at,entry_closes_at)
select '72000000-0000-4000-8000-000000000002',created_by,'Cover SQL lifecycle',venue,event_date,max_capacity,time_zone,registration_closes_at,entry_opens_at,entry_closes_at from public.events where id='72000000-0000-4000-8000-000000000001';
select is((select revision from public.event_covers where event_id='72000000-0000-4000-8000-000000000002'),0::bigint,'New Event gets empty revision zero');
set local role authenticated;
set local request.jwt.claims='{"sub":"71000000-0000-4000-8000-000000000002"}';
select is((select count(*) from public.event_covers),0::bigint,'RLS excludes other owners and door-only actors');
set local request.jwt.claims='{"sub":"71000000-0000-4000-8000-000000000001"}';
select ok((select count(*)>0 from public.event_covers),'Owner reads cover under RLS');
reset role;
update public.event_covers set object_path='covers/'||repeat('a',64), media_type='image/png',byte_size=5242880,width=640,height=360,content_hash=repeat('b',64),alt_text='Original',position_x=0.25,position_y=0.75 where event_id='72000000-0000-4000-8000-000000000002';
select throws_ok($$update public.event_covers set byte_size=5242881 where object_path is not null$$,'23514',null,'One byte above inclusive maximum rejected');
select throws_ok($$update public.event_covers set width=639 where object_path is not null$$,'23514',null,'Width minimum independent');
select throws_ok($$update public.event_covers set height=359 where object_path is not null$$,'23514',null,'Height minimum independent');
select throws_ok($$update public.event_covers set alt_text='   ' where object_path is not null$$,'23514',null,'Persistence requires normalized custom alternative');
select is(public.mutate_event_cover('72000000-0000-4000-8000-000000000002','71000000-0000-4000-8000-000000000001',repeat('c',64),'metadata',0,repeat('d',64),'{"altText":null}')->>'status','committed','Metadata commits under owner CAS');
select is((select revision from public.event_covers where event_id='72000000-0000-4000-8000-000000000002'),1::bigint,'Metadata increments once');
select ok((select alt_text is null and position_x=0.25 and position_y=0.75 from public.event_covers where event_id='72000000-0000-4000-8000-000000000002'),'Omitted position preserved; cleared alternative derives publicly');
select is(public.mutate_event_cover('72000000-0000-4000-8000-000000000002','71000000-0000-4000-8000-000000000001',repeat('c',64),'metadata',0,repeat('d',64),'{"altText":null}')->'result'->>'revision','1','Metadata replay returns original durable result');
select is(public.mutate_event_cover('72000000-0000-4000-8000-000000000002','71000000-0000-4000-8000-000000000001',repeat('e',64),'remove',0,repeat('f',64),'{}')->>'status','conflict','Stale removal cannot overwrite winner');
select is(public.mutate_event_cover('72000000-0000-4000-8000-000000000002','71000000-0000-4000-8000-000000000001',repeat('1',64),'remove',1,repeat('2',64),'{}')->>'status','committed','Removal commits');
select ok((select revision=2 and object_path is null and alt_text is null and position_x=0.5 and position_y=0.5 from public.event_covers where event_id='72000000-0000-4000-8000-000000000002'),'Removal clears file and metadata, centers position');
select ok(exists(select 1 from public.event_cover_cleanup_jobs where object_path='covers/'||repeat('a',64)),'Removal enqueues previous immutable path');
select is(public.mutate_event_cover('72000000-0000-4000-8000-000000000002','71000000-0000-4000-8000-000000000001',repeat('3',64),'remove',2,repeat('4',64),'{}')->'result'->>'revision','2','Removing absent file with current revision is a no-op');
select is(public.mutate_event_cover('72000000-0000-4000-8000-000000000002','71000000-0000-4000-8000-000000000001',repeat('5',64),'metadata',2,repeat('6',64),'{"positionX":0.5}')->>'status','conflict','Metadata without a file conflicts');
select throws_ok($$select public.mutate_event_cover('72000000-0000-4000-8000-000000000002','71000000-0000-4000-8000-000000000002',repeat('7',64),'remove',2,repeat('8',64),'{}')$$,'42501','cover_forbidden','Non-owner cannot maintain cover');
select * from finish();
rollback;
